import {
  Activity, AlertTriangle, ArrowRight, BadgeCheck, Bell, Bot, Check,
  CheckCircle2, ChevronRight, ClipboardCheck, FileCheck2, IndianRupee,
  LayoutDashboard, ListChecks, LocateFixed, LogOut, MapPin, Menu, Package, Percent,
  ReceiptText, RefreshCcw, Search, Send, Settings, ShieldCheck, ShoppingBag, Sparkles, Store, Upload,
  Users, WalletCards
} from "lucide-react";
import { toast } from "sonner";
import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Progress } from "@/components/ui/progress";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
